"""Tíz eltérő elrendezés, helyi assetekkel és adatbázisból számolt mutatókkal."""
from html import escape
from core import query

BRANDS={1:('SocialHub','Csapathírek','SH'),2:('LocalMail','Levelezés','LM'),3:('MarketLab','Webáruház','ML'),4:('HelpDesk','Ügyfélszolgálat','HD'),5:('PeopleOps','Személyügy','PO'),6:('TeamWiki','Belső tudástár','TW'),7:('EventDesk','Rendezvények','ED'),8:('StayLab','Szállásfoglalás','SL'),9:('SalesFlow','Ügyfélkezelés','SF'),10:('BuildBoard','Fejlesztés','BB')}
SPECIAL={1:('Profil és moderáció','profile'),2:('Címjegyzék és keresés','contacts'),3:('Kosár és kuponok','checkout'),4:('Triage és SLA','triage'),5:('Bérkimutatás','payroll'),6:('Szerkesztő és publikálás','editor'),7:('Előadóimport és program','speakers'),8:('Foglalás és ajánlatkérés','quote'),9:('Riportsablonok','analytics'),10:('Webhook és buildnapló','integrations')}
CSS='''
:root{--bg:#f4f6fa;--paper:white;--ink:#1e293b;--muted:#748095;--accent:#635bff;--line:#e5eaf1;--radius:7px;--soft:#eeecff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.6 system-ui,-apple-system,Segoe UI,sans-serif}a{color:var(--accent);text-decoration:none}button,.btn{border:0;background:var(--accent);color:white;border-radius:9px;padding:11px 18px;font:600 13px system-ui;cursor:pointer;display:inline-block}button:hover,.btn:hover{filter:brightness(.94)}input,textarea,select{border:1px solid var(--line);background:var(--paper);color:var(--ink);padding:11px 13px;border-radius:8px;font:inherit;max-width:100%}input[type=checkbox]{width:auto}textarea{min-height:110px;width:100%;display:block;margin:10px 0}input,select{margin:4px}form{margin:14px 0}label{display:inline-block;font-size:13px}h1{font-size:25px;line-height:1.3;margin:0 0 10px;letter-spacing:-.3px}h2{font-size:20px;letter-spacing:-.4px;margin:0 0 12px}h3{font-size:16px;margin:0 0 8px}p{margin:8px 0}small,.muted{color:var(--muted)}.eyebrow{letter-spacing:.2px;font-size:11px;font-weight:500;color:var(--muted)}.app{min-height:100vh;display:grid;grid-template-columns:222px 1fr}.sidebar{padding:28px 18px;background:var(--paper);border-right:1px solid var(--line);display:flex;flex-direction:column;gap:6px}.brand{display:flex;align-items:center;gap:10px;color:var(--ink);font-size:20px;font-weight:800;margin:0 8px 30px}.brand em{font-style:normal;width:38px;height:38px;background:var(--accent);color:white;display:grid;place-items:center;border-radius:6px;font-size:12px}.sidebar nav a{display:block;padding:11px 14px;border-radius:9px;color:var(--muted);font-weight:600;margin:3px 0}.sidebar nav a.active{background:var(--soft);color:var(--accent)}.sidebar footer{margin-top:auto;padding:30px 12px 0;font-size:11px;color:var(--muted)}.workspace{min-width:0}.topbar{height:78px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;background:var(--paper);border-bottom:1px solid var(--line)}.user{display:flex;align-items:center;gap:12px}.avatar{width:38px;height:38px;border-radius:50%;background:var(--soft);color:var(--accent);display:inline-grid;place-items:center;font-weight:700;flex-shrink:0}.content{padding:28px;max-width:1500px;margin:auto}.page-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:26px}.page-head p{color:var(--muted)}.panel,article{border:1px solid var(--line);background:var(--paper);border-radius:var(--radius);padding:22px;margin-bottom:18px}.grid{display:grid;gap:20px}.g2{grid-template-columns:repeat(2,minmax(0,1fr))}.g3{grid-template-columns:repeat(3,minmax(0,1fr))}.g4{grid-template-columns:repeat(4,minmax(0,1fr))}.stats{display:flex;gap:18px;margin-bottom:25px}.stat{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);padding:19px 22px;flex:1}.stat strong{font-size:25px;display:block;line-height:1.4}.badge{display:inline-block;background:var(--soft);color:var(--accent);border-radius:6px;padding:3px 10px;font-size:10px;font-weight:700}.row{display:flex;align-items:center;gap:12px}.between{justify-content:space-between}.stack{display:grid;gap:14px}.price{font-size:24px;font-weight:800}.visual{height:145px;background:var(--soft);border-radius:6px;position:relative;overflow:hidden;margin-bottom:18px;display:grid;place-items:center;font-size:46px;color:white}.unused-decoration:after{content:'';position:absolute;width:150px;height:150px;border:25px solid #ffffff25;border-radius:50%;right:-35px;bottom:-70px}.search{display:flex;gap:8px;flex-wrap:wrap}.search input[name=q]{flex:1;min-width:180px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:13px 12px;border-bottom:1px solid var(--line);text-align:left}th{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:var(--muted)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--soft);padding:16px;border-radius:10px}section{min-width:0}.columns{display:grid;gap:24px;grid-template-columns:220px minmax(0,1fr) 260px}.feed article{padding:24px}.columns .stats{display:block}.columns .stat{margin:10px 0}.columns .stat strong{font-size:24px}.feed .post-text{font-size:15px;margin:18px 0}.feed-actions{border-top:1px solid var(--line);padding-top:15px;display:flex;gap:25px;font-size:12px}.mail-layout{display:grid;grid-template-columns:330px minmax(0,1fr);min-height:580px;background:var(--paper);border:1px solid var(--line);border-radius:6px;overflow:hidden}.mail-list{border-right:1px solid var(--line)}.mail-list a{display:block;padding:20px;color:var(--ink);border-bottom:1px solid var(--line)}.mail-list a:hover{background:var(--soft)}.mail-reader{padding:35px}.mail-reader article{border:0;padding:0}.lanes{display:flex;gap:16px;align-items:flex-start;overflow:auto}.lane{min-width:210px;flex:1;background:var(--soft);padding:14px;border-radius:6px}.lane h3{font-size:11px;letter-spacing:1px;text-transform:uppercase;padding:8px}.lane article{padding:17px;margin:12px 0}.hero{border-radius:6px;padding:42px;background:var(--accent);color:white;margin-bottom:25px;position:relative;overflow:hidden}.hero h1{font-size:28px;max-width:700px}.hero a{color:inherit}.hero .eyebrow{color:#ffffffaa}.hero .btn{background:white;color:var(--accent);margin-top:20px}.toc{border-right:1px solid var(--line);padding:10px}.toc a{display:block;padding:9px 0;color:var(--muted)}.document{font-family:Georgia,serif;font-size:17px;line-height:1.9;padding:18px 42px}.document h1{font-size:40px}.progress{height:7px;border-radius:5px;background:var(--line);overflow:hidden;margin-top:8px}.progress i{display:block;height:100%;background:var(--accent)}.month{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}.day{padding:10px;background:var(--soft);text-align:center;border-radius:7px}.date-tile{background:var(--soft);padding:16px;border-radius:6px;text-align:center;min-width:70px}.date-tile strong{display:block;font-size:29px}.toolbar{display:flex;gap:10px;align-items:center;margin-bottom:22px;flex-wrap:wrap}.login{max-width:450px;margin:55px auto}.login input{width:100%;margin:8px 0}.login button{width:100%}.notice{padding:12px 18px;background:var(--soft);border-radius:9px;font-size:12px}.app.p2{--bg:#edf1f5;--accent:#087e8b;--soft:#e0f4f2;--radius:8px;grid-template-columns:190px 1fr}.p2 .sidebar{background:#093a43;color:white}.p2 .brand,.p2 .sidebar nav a{color:#d1e8e9}.p2 .sidebar nav a.active{color:#093a43}.p2 .topbar{height:64px}.app.p3{--accent:#e37827;--soft:#fff0df;--bg:#fffdf9;--radius:12px;display:block}.p3 .sidebar{padding:14px 35px;flex-direction:row;align-items:center;border-bottom:1px solid var(--line)}.p3 .brand{margin:0 28px 0 0}.p3 .sidebar nav{display:flex;flex-wrap:wrap}.p3 .sidebar footer{display:none}.p3 .topbar{height:50px}.p3 .content{max-width:1350px}.app.p4{--accent:#3157db;--soft:#e9efff;--bg:#f2f5fa;--radius:7px;grid-template-columns:190px 1fr}.p4 .sidebar{background:#162440}.p4 .brand,.p4 .sidebar nav a{color:#b9c6df}.p4 .sidebar nav a.active{color:#3157db}.p4 td{padding:18px 12px}.app.p5{--accent:#8a5b45;--soft:#f5e9df;--bg:#f9f5ef;--radius:8px}.p5 .sidebar{background:#f1e9dc}.p5 h1,.p5 h2{font-family:Georgia,serif;font-weight:500}.p5 .avatar{border-radius:14px}.app.p6{--accent:#466151;--soft:#edf1e9;--bg:#fffefa;--radius:4px;grid-template-columns:235px 1fr}.p6 .sidebar{background:#f3f3ee}.p6 .topbar{height:60px;background:transparent}.app.p7{--bg:#11101d;--paper:#1c192c;--ink:#f6f1ff;--muted:#b0a9bf;--accent:#b595ff;--soft:#302742;--line:#352e46;--radius:9px;display:block}.p7 .sidebar{flex-direction:row;align-items:center;padding:16px 35px}.p7 .brand{margin:0 30px 0 0}.p7 .sidebar nav{display:flex;flex-wrap:wrap}.p7 .sidebar footer{display:none}.p7 .hero{background:#302742;padding:55px}.p7 .hero h1{font-size:30px}.p7 .topbar{height:48px}.app.p8{--accent:#087c73;--soft:#e5f4ef;--bg:#faf9f6;--radius:9px;display:block}.p8 .sidebar{flex-direction:row;padding:15px 40px;align-items:center}.p8 .brand{margin:0 40px 0 0}.p8 .sidebar nav{display:flex;flex-wrap:wrap}.p8 .sidebar footer{display:none}.p8 .topbar{height:46px}.p8 .hero{background:#e5f4ef}.app.p9{--accent:#6554c0;--soft:#efecfa;--radius:10px;grid-template-columns:205px 1fr}.p9 .sidebar{background:#282044}.p9 .brand,.p9 .sidebar nav a{color:#d0c9e6}.p9 .sidebar nav a.active{color:#6554c0}.p9 .lane{min-width:215px}.app.p10{--bg:#101319;--paper:#191e27;--ink:#e0e6ed;--muted:#8d99aa;--accent:#58c6a1;--soft:#222d34;--line:#2a333f;--radius:8px;grid-template-columns:200px 1fr}.p10 .brand,.p10 h1,.p10 .eyebrow{font-family:ui-monospace,monospace}.p10 .topbar{height:60px}.p10 pre{color:#8ee5bd;background:#0b1016}.p10 .lane{background:#141920}.p10 .sidebar{background:#141820}.p10 button{color:#10241e}.subgrid{display:grid;grid-template-columns:1fr 320px;gap:24px}.hub{max-width:1250px;margin:50px auto;padding:25px}.hub-card{padding:28px;background:var(--paper);border:1px solid var(--line);border-radius:7px}.hub-card em{font-style:normal;display:block;font-size:30px;color:var(--accent)}details{padding:12px 0}summary{cursor:pointer;color:var(--muted)}.scroll-table{overflow:auto}
@media(max-width:1100px){.columns{grid-template-columns:1fr 250px}.columns>aside:first-child{display:none}.g4{grid-template-columns:repeat(2,1fr)}.sidebar{padding:20px 10px}.app{grid-template-columns:180px 1fr}.content{padding:22px}.subgrid{grid-template-columns:1fr}.g3{grid-template-columns:repeat(2,1fr)}}@media(max-width:740px){.app,.app.p2,.app.p4,.app.p6,.app.p9,.app.p10{display:block}.sidebar{display:block!important;padding:12px!important}.sidebar .brand{margin:0 0 8px!important}.sidebar nav{display:flex!important;overflow:auto;flex-wrap:nowrap!important;white-space:nowrap}.sidebar footer{display:none}.sidebar nav a{font-size:11px;padding:8px}.topbar{padding:10px 16px;height:auto!important;gap:10px}.content{padding:18px}.columns,.mail-layout,.g2,.g3,.g4{display:block}.columns>aside{display:none}.mail-list{border-right:0}.mail-reader{padding:20px}.stats{flex-wrap:wrap}.stat{min-width:120px}.hero,.p7 .hero{padding:25px}.hero h1,.p7 .hero h1{font-size:32px}.page-head{align-items:flex-start}.user small{display:none}.document{padding:10px;font-size:16px}.sidebar nav a.active{background:var(--soft)}.grid>*{margin-bottom:16px}}
.test-options{display:inline-block;font-size:11px;align-self:center;padding:0;margin-left:8px}.test-options[open]{padding:6px 10px;border:1px solid var(--line);border-radius:5px}.test-options summary{font-size:11px}.catalog-label{border-bottom:1px solid var(--line);padding:8px 0 12px;margin-bottom:14px;font-size:11px;color:var(--muted)}.catalog-label b{font-family:ui-monospace,monospace;font-weight:500}.listing{display:grid;grid-template-columns:1fr auto;gap:18px;border-bottom:1px solid var(--line);padding:22px 0}.listing:last-child{border-bottom:0}.listing h3{font-size:19px}.listing p{max-width:680px}.staff-info{font-size:12px;line-height:1.8}.staff-card .avatar{width:45px;height:45px}.section-heading{border-bottom:1px solid var(--line);padding-bottom:12px;margin-bottom:20px}.empty{padding:22px;color:var(--muted)}.p8 .hero{color:var(--ink)}.p7 .hero{padding:24px}.document h1{font-size:30px}.brand em{border-radius:4px}.brand{font-size:18px}.app .hero{padding:24px}.app .hero p{max-width:700px}.hub-card{border-left:3px solid var(--accent)}.hub-card em{font-size:16px;font-weight:600;margin-bottom:15px}.hub{max-width:1100px}.page-head:has(+ .mail-layout){margin-bottom:18px}

'''

def e(v): return escape(str(v),quote=True)

def render(p,title,body,account=None,sub=''):
    brand,tag,initial=BRANDS[p]; pre=f'/p{p:02d}'
    labels={1:['Hírfolyam','Új bejegyzés','Követések'],2:['Áttekintés','Új sablon','Levelezési napló'],3:['Katalógus','Új termék','Kosár'],4:['Ügyfélszolgálat','Új hibajegy','Ügyintézők'],5:['Munkatársak','Új adatlap','Szabadságok'],6:['Tudásközpont','Új dokumentum','Verziók'],7:['Rendezvények','Új esemény','Regisztrációk'],8:['Szálláskeresés','Új szállás','Foglalások'],9:['Értékesítési tábla','Új ügyfél','Értékesítés'],10:['Feladattábla','Új feladat','Függőségek']}[p]
    links=[('',labels[0]),('new',labels[1]),('workflow',labels[2]),(SPECIAL[p][1],SPECIAL[p][0]),('report','Mentett riportok')]
    if p==2: links[1:1]=[('inbox','Beérkező levelek'),('compose','Levélírás')]
    nav=''.join(f'<a class="{"active" if sub==url else ""}" href="{pre}/{url}">{e(label)}</a>' for url,label in links)
    username=account['username'] if account else 'Vendég'
    role=account['role'] if account else 'Nincs bejelentkezve'
    if sub=='login': body='<div class="panel login"><h1>Belépés</h1>'+body+'</div>'
    return f'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><style>{CSS}</style></head><body><div class="app p{p}" data-layout="{p}"><aside class="sidebar"><a class="brand" href="{pre}/"><em>{initial}</em>{brand}</a><nav>{nav}</nav><footer><a href="/">Alkalmazásválasztó</a><br><a href="{pre}/logout">Kijelentkezés</a></footer></aside><div class="workspace"><header class="topbar"><div><span class="eyebrow">{e(tag)}</span><div>{e(SPECIAL[p][0]) if sub==SPECIAL[p][1] else e(brand)}</div></div><div class="user"><small>Bejelentkezve: {e(username)}<br>{e(role)}</small><span class="avatar">{e(username[:1].upper())}</span><a href="/">Alkalmazások</a></div></header><main class="content">{body}</main></div></div><script>document.querySelectorAll('table').forEach(t=>{{let w=document.createElement('div');w.className='table-wrap';t.parentNode.insertBefore(w,t);w.appendChild(t);}});</script></body></html>'''

def stats(values):
    return '<div class="stats">'+''.join(f'<div class="stat"><small>{e(k)}</small><strong>{e(v)}</strong></div>' for k,v in values)+'</div>'

def search(q):
    return f'<form class="search"><input name="q" value="{e(q)}" placeholder="Keresés"><button>Keresés</button><details class="test-options"><summary>Tesztbeállítások</summary><label><input type="checkbox" name="safe" value="1">Kontroll</label></details></form>'

STATE_LABELS={'published':'Közzétéve','draft':'Piszkozat','internal':'Belső','open':'Nyitott','progress':'Folyamatban','closed':'Lezárt','active':'Aktív','leave':'Szabadságon','done':'Kész','lead':'Új érdeklődő','qualified':'Egyeztetés','proposal':'Ajánlat','won':'Megnyert','lost':'Elvesztett'}

def badge(value):
    return '<span class="badge" data-status="'+e(value)+'">'+e(STATE_LABELS.get(value,value))+'</span>'

def home(p,uid,rows,params):
    pre=f'/p{p:02d}'
    username={1:'Anna',2:'Béla',3:'Admin'}.get(uid,'Felhasználó')
    def link(r): return f'{pre}/item?id={r["id"]}'
    def card(r,extra=''):
        return f'<article><a href="{link(r)}"><h3>{e(r["title"])}</h3></a><p>{badge(r["status"])}</p>{extra}</article>'
    titles={1:'Hírfolyam',2:'Levelezés',3:'Termékek',4:'Hibajegyek',5:'Munkatársak',6:'Dokumentumok',7:'Rendezvények',8:'Szállások',9:'Értékesítési tábla',10:'Feladatok'}
    actions={1:'Új bejegyzés',2:'Új sablon',3:'Termék felvétele',4:'Hibajegy nyitása',5:'Új munkatárs',6:'Új oldal',7:'Új rendezvény',8:'Szállás felvétele',9:'Új ügyfél',10:'Új feladat'}
    top=f'<div class="page-head"><h1>{titles[p]}</h1><a class="btn" href="{pre}/new">{actions[p]}</a></div>'
    s=search(params.get('q',''))
    if params.get('safe')=='1': s=s.replace('type="checkbox"','type="checkbox" checked')
    if not rows: return top+s+'<div class="panel">Nincs találat.</div>'
    count=len(rows)
    notes=query('SELECT COUNT(*) AS n FROM notes WHERE project=?',(p,))[0]['n']
    if p==1:
        posts=''.join(f'<article><div class="row between"><div class="row"><span class="avatar">{e(r["owner"][:1].upper())}</span><b>{e(r["owner"])}</b></div>{badge(r["status"])}</div><a href="{link(r)}"><h2 class="post-text">{e(r["title"])}</h2></a><p>{e(r.get("body",""))}</p><div class="feed-actions"><a href="{link(r)}">Hozzászólások</a><a href="{pre}/workflow">Követés</a></div></article>' for r in rows)
        return top+f'<div class="columns"><aside><div class="panel"><span class="avatar">{e(username[:1])}</span><h3 style="margin-top:12px">{e(username)}</h3><a href="{pre}/profile">Profil szerkesztése</a></div><div class="panel"><h3>Bejegyzések</h3><p><a href="{pre}/">Összes</a></p><p><a href="{pre}/workflow">Követett felhasználók</a></p><p><a href="{pre}/report">Mentett keresések</a></p></div></aside><section class="feed">{s}<article><a href="{pre}/new">Új bejegyzés írása</a></article>{posts}</section><aside><div class="panel"><h3>Összesítés</h3>{stats([("Bejegyzések",count),("Hozzászólások",notes)])}</div><div class="panel"><h3>Tagok</h3><p>Anna</p><p>Béla</p><p>Admin</p></div></aside></div>'
    if p==2:
        mails=query('SELECT sender,subject,body FROM mail WHERE project=2 AND recipient=? ORDER BY rowid DESC',({1:'anna',2:'bela',3:'admin'}[uid]+'@example.test',))
        listing=''.join(f'<a href="{pre}/inbox?read={i}"><b>{e(m["sender"])}</b><h3>{e(m["subject"])}</h3></a>' for i,m in enumerate(mails))
        templates=''.join(f'<p><a href="{link(r)}">{e(r["title"])}</a></p>' for r in rows[:6])
        return top+f'<div class="toolbar"><a class="btn" href="{pre}/compose">Levélírás</a><span class="muted">{len(mails)} beérkezett levél</span><a href="{pre}/contacts">Címjegyzék</a></div><div class="mail-layout"><div class="mail-list">{listing or "<div class=empty>Üres postafiók</div>"}</div><div class="mail-reader"><h2>Levélsablonok</h2><p class="muted">Válassz levelet a listából, vagy nyiss meg egy mentett sablont.</p>{s}{templates}</div></div>'
    if p==3:
        products={r['item_id']:r for r in query('SELECT * FROM products')}
        categories={'office':'Iroda','tech':'Technika','accessory':'Kiegészítők'}
        cards=''
        for r in rows:
            product=products.get(r['id'],{})
            category=categories.get(product.get('category'),'Egyéb')
            cards+=f'<article><div class="catalog-label"><b>{e(product.get("sku","ML-"+str(r["id"])))}</b> · {category}</div><a href="{link(r)}"><h3>{e(r["title"])}</h3></a><p class="muted">{product.get("stock",0)} db készleten</p><div class="row between"><span class="price">{r["amount"]:,} Ft</span><a href="{pre}/checkout?add={r["id"]}">Kosárba</a></div></article>'
        return top+s+f'<div class="toolbar"><span class="muted">{count} termék</span><a href="{pre}/checkout">Kosár megnyitása</a></div><div class="grid g3">'+cards+'</div>'
    if p==4:
        ticketrows=''.join(f'<tr><td><a href="{link(r)}">HD-{r["id"]:04d}</a></td><td><b>{e(r["title"])}</b></td><td>{badge(r["status"])}</td><td>{e(r["owner"])}</td><td><a href="{pre}/triage">Kiosztás</a></td></tr>' for r in rows)
        open_count=sum(r['status']=='open' for r in rows)
        progress_count=sum(r['status']=='progress' for r in rows)
        return top+stats([('Összes hibajegy',count),('Nyitott',open_count),('Folyamatban',progress_count)])+f'<div class="subgrid"><section class="panel">{s}<table><tr><th>Azonosító</th><th>Tárgy</th><th>Állapot</th><th>Bejelentő</th><th></th></tr>{ticketrows}</table></section><aside><div class="panel"><h3>Ügyintézés</h3><p><a href="{pre}/triage">Prioritás és SLA</a></p><p><a href="{pre}/workflow">Ügyintéző kijelölése</a></p><p><a href="{pre}/report">Mentett szűrők</a></p></div></aside></div>'
    if p==5:
        employees={r['item_id']:r for r in query('SELECT * FROM employees')}
        cards=''
        for r in rows:
            employee=employees.get(r['id'],{})
            initials=''.join(word[0] for word in r['title'].split()[:2])
            cards+=f'<article class="staff-card"><div class="row"><span class="avatar">{e(initials)}</span><div><a href="{link(r)}"><h3>{e(r["title"])}</h3></a><small>{e(employee.get("department",""))}</small></div></div><p class="staff-info">{e(employee.get("location",""))}<br>{e(employee.get("leave_days",0))} nap szabadság</p>{badge(r["status"])}</article>'
        leave_count=query('SELECT COUNT(*) AS n FROM workflow WHERE project=5')[0]['n']
        return top+stats([('Munkatárs',count),('Szabadságkérelem',leave_count),('Szabadságon',sum(r['status']=='leave' for r in rows))])+s+'<div class="grid g3">'+cards+'</div>'
    if p==6:
        toc=''.join(f'<a href="{link(r)}">{e(r["title"])}</a>' for r in rows)
        return '<div class="grid" style="grid-template-columns:225px minmax(0,1fr)"><aside class="toc"><h3>Oldalak</h3>'+toc+f'</aside><section class="document"><h1>Tudástár</h1>{s}<h2>Dokumentumok</h2>'+''.join(f'<article><a href="{link(r)}"><h3>{e(r["title"])}</h3></a><p class="muted">{e(r.get("body","")[:160])}</p></article>' for r in rows[:6])+f'<a href="{pre}/editor">Oldal szerkesztése</a></section></div>'
    if p==7:
        cards=''.join(f'<article><p class="muted">Esemény #{r["id"]}</p><a href="{link(r)}"><h2>{e(r["title"])}</h2></a><p>{e(r.get("body",""))}</p><div class="row between">{badge(r["status"])}<a href="{pre}/workflow">Jelentkezés</a></div></article>' for r in rows)
        return top+f'<div class="toolbar"><a href="{pre}/speakers">Előadók és program</a><a href="{pre}/workflow">Regisztrációk</a></div>'+s+'<div class="grid g2">'+cards+'</div>'
    if p==8:
        properties={r['item_id']:r for r in query('SELECT * FROM properties')}
        listings=''
        for r in rows:
            prop=properties.get(r['id'],{})
            listings+=f'<div class="listing"><div><p class="muted">{e(prop.get("city",""))}</p><a href="{link(r)}"><h3>{e(r["title"])}</h3></a><p>{e(r.get("body",""))}</p><small>{e(prop.get("beds",0))} férőhely · {e(prop.get("amenities",""))}</small></div><div><p class="price">{r["amount"]:,} Ft</p><p class="muted">éjszakánként</p><a class="btn" href="{pre}/quote?id={r["id"]}">Ajánlatkérés</a></div></div>'
        return top+s+'<section class="panel">'+listings+'</section>'
    if p==9:
        lanes=''
        for stage in ['lead','qualified','proposal','won','lost']:
            deals=[r for r in rows if r['status']==stage]
            lanes+=f'<div class="lane"><h3>{STATE_LABELS[stage]} <span class="badge">{len(deals)}</span></h3>'+''.join(card(r,f'<strong>{r["amount"]:,} Ft</strong><p class="muted">Felelős: {e(r["owner"])}</p>') for r in deals)+'</div>'
        return top+stats([('Nyilvántartott érték',f'{sum(r["amount"] for r in rows):,} Ft'),('Ügyfelek',count),('Megjegyzések',notes)])+s+f'<div class="toolbar"><a href="{pre}/analytics">Riportsablonok</a><a href="{pre}/workflow">Fázis módosítása</a></div><div class="lanes">'+lanes+'</div>'
    lanes=''
    for stage,label in [('open','Tervezett'),('progress','Folyamatban'),('done','Kész')]:
        items=[r for r in rows if r['status']==stage]
        lanes+=f'<div class="lane"><h3>{label} <span class="badge">{len(items)}</span></h3>'+''.join(card(r,f'<div class="row between"><small>BB-{r["id"]:03d}</small><small>{e(r["owner"])}</small></div>') for r in items)+'</div>'
    return top+s+f'<div class="toolbar"><span class="muted">{count} feladat</span><a href="{pre}/integrations">Buildnapló</a><a href="{pre}/workflow">Függőségek</a></div><div class="lanes">'+lanes+'</div>'


def hub(selected=None):
    cards=''
    colors=['#635bff','#087e8b','#e37827','#3157db','#8a5b45','#466151','#b595ff','#087c73','#6554c0','#58c6a1']
    for p,(brand,tag,initial) in BRANDS.items():
        if selected and selected!=p: continue
        cards+=f'<a class="hub-card" style="--accent:{colors[p-1]}" href="/p{p:02d}/"><em>{initial}</em><span class="eyebrow">/{p:02d}</span><h2>{brand}</h2><p class="muted">{tag}</p><p>{SPECIAL[p][0]}</p></a>'
    return '<!doctype html><html lang="hu"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Security Lab 2</title><style>'+CSS+'</style><body><main class="hub"><span class="eyebrow">Tesztkörnyezet</span><h1>Alkalmazások</h1><p class="muted">Válaszd ki a megnyitni kívánt alkalmazást.</p><p class="notice">Tesztfiókok: anna, bela, admin · Jelszó: LabPass123! · Minden adat kitalált.</p><div class="grid g3" style="margin-top:30px">'+cards+'</div></main></body></html>'

def inbox(rows,params):
    safe=params.get('safe')=='1'
    index=max(0,min(len(rows)-1,int(params.get('read','0'))))
    listing=''.join('<a href="?read='+str(i)+('&safe=1' if safe else '')+'"><b>'+e(r['sender'])+'</b><h3>'+e(r['subject'])+'</h3><small>'+e(r['body'][:70])+'</small></a>' for i,r in enumerate(rows))
    if rows:
        r=rows[index]
        reader='<span class="eyebrow">BEÉRKEZŐ LEVÉL</span><h1>'+e(r['subject'])+'</h1><p class="muted">Feladó: '+e(r['sender'])+'</p><hr><article>'+(e(r['body']) if safe else r['body'])+'</article>'
    else: reader='<h2>Üres postafiók</h2>'
    return '<div class="toolbar"><a class="btn" href="/p02/compose">+ Új üzenet</a><a href="?read='+str(index)+'&safe=1">Szöveges nézet</a><a href="/p02/contacts">Címjegyzék</a></div><div class="mail-layout"><div class="mail-list">'+listing+'</div><div class="mail-reader">'+reader+'</div></div>'
